import React, { useState, useEffect, useRef, useCallback } from 'react';
import { VideoOff, Clock, Volume2, Mic, CheckCircle, AlertCircle } from 'lucide-react';

// Safe imports with fallbacks
let VoiceEngine;
let SpeechSynthesisEngine;
let generateInterviewQuestions;
let scoreAnswerWithAI;

try {
  VoiceEngine = require('../ai/VoiceEngine').VoiceEngine;
} catch (error) {
  console.warn('VoiceEngine not available, using fallback');
  VoiceEngine = class {
    start() { 
      console.log('VoiceEngine fallback: start');
      return false; 
    }
    stop() { 
      console.log('VoiceEngine fallback: stop');
      return ''; 
    }
    abort() { console.log('VoiceEngine fallback: abort'); }
    setCallbacks() { console.log('VoiceEngine fallback: setCallbacks'); }
    isActive() { return false; }
  };
}

try {
  SpeechSynthesisEngine = require('../ai/SpeechSynthesis').SpeechSynthesisEngine;
} catch (error) {
  console.warn('SpeechSynthesisEngine not available, using fallback');
  SpeechSynthesisEngine = class {
    async initialize() { 
      console.log('SpeechSynthesisEngine fallback: initialize');
      return true;
    }
    async speak(text, options) { 
      console.log('SpeechSynthesisEngine fallback: speak', text);
      if (options?.onEnd) {
        setTimeout(options.onEnd, 1000);
      }
    }
    stop() { console.log('SpeechSynthesisEngine fallback: stop'); }
  };
}

try {
  const geminiAI = require('../ai/GeminiAI');
  generateInterviewQuestions = geminiAI.generateRealisticInterviewQuestions;
  scoreAnswerWithAI = geminiAI.scoreAnswerWithAI;
} catch (error) {
  console.warn('GeminiAI not available, using fallbacks');
  generateInterviewQuestions = async () => {
    console.log('generateInterviewQuestions fallback');
    return [
      { id: 1, question: 'Tell me about yourself and your experience.', difficulty: 'Easy', time: 120, type: 'introduction' },
      { id: 2, question: 'What are your strengths and weaknesses?', difficulty: 'Medium', time: 90, type: 'warmup' },
      { id: 3, question: 'Where do you see yourself in 5 years?', difficulty: 'Hard', time: 180, type: 'technical' }
    ];
  };

  scoreAnswerWithAI = async (question, answer, difficulty) => {
    console.log('scoreAnswerWithAI fallback');
    return {
      score: Math.floor(Math.random() * 10) + 5,
      feedback: 'This is a simulated evaluation. AI service is not available.'
    };
  };
}

const VideoInterviewPage = ({ candidate, onComplete, onBack }) => {
  const [stream, setStream] = useState(null);
  const [isRecording, setIsRecording] = useState(false);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [questions, setQuestions] = useState([]);
  const [timeRemaining, setTimeRemaining] = useState(null);
  const [transcript, setTranscript] = useState('');
  const [isAISpeaking, setIsAISpeaking] = useState(false);
  const [status, setStatus] = useState('initializing');
  const [error, setError] = useState('');

  const videoRef = useRef(null);
  const voiceEngine = useRef(null);
  const speechEngine = useRef(null);
  const timerRef = useRef(null);
  const answersRef = useRef([]);
  const isProcessingRef = useRef(false);
  const hasInitialized = useRef(false);

  // ⭐ FIXED: Safe voice engine start
  const startRecording = useCallback(() => {
    if (!voiceEngine.current) {
      console.error('Voice engine not initialized');
      return false;
    }

    if (voiceEngine.current.isActive && voiceEngine.current.isActive()) {
      console.warn('⚠️ Already recording, skipping start');
      return true;
    }

    if (isRecording) {
      console.warn('⚠️ isRecording flag is true, skipping start');
      return true;
    }

    console.log('🎤 Starting voice recording...');
    const started = voiceEngine.current.start();

    if (started) {
      setIsRecording(true);
      console.log('✅ Recording started successfully');
      return true;
    } else {
      console.error('❌ Failed to start recording');
      return false;
    }
  }, [isRecording]);

  // ⭐ FIXED: Safe voice engine stop
  const stopRecording = useCallback(() => {
    if (!voiceEngine.current) return '';

    console.log('🛑 Stopping voice recording...');
    const finalTranscript = voiceEngine.current.stop();
    setIsRecording(false);

    console.log('✅ Recording stopped. Transcript:', finalTranscript);
    return finalTranscript || transcript;
  }, [transcript]);

  // Cleanup media and engines
  const cleanup = useCallback(() => {
    console.log('🧹 Cleaning up resources...');

    if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }

    if (voiceEngine.current) {
      voiceEngine.current.abort?.();
      voiceEngine.current = null;
    }

    if (speechEngine.current) {
      speechEngine.current.stop();
      speechEngine.current = null;
    }

    if (stream) {
      stream.getTracks().forEach(track => track.stop());
      setStream(null);
    }
  }, [stream]);

  // Text-to-speech
  const speakText = useCallback(async (text) => {
    if (!speechEngine.current) return;

    if (isRecording) {
      stopRecording();
    }

    setIsAISpeaking(true);
    console.log('🗣️ AI Speaking:', text);

    try {
      await speechEngine.current.speak(text, {
        rate: 0.95,
        pitch: 1.1,
        volume: 1.0,
        onEnd: () => {
          console.log('✅ AI finished speaking');
          setIsAISpeaking(false);
        },
      });
    } catch (err) {
      console.error('Speech error:', err);
      setIsAISpeaking(false);
    }
  }, [isRecording, stopRecording]);

  // Complete interview
  const completeInterview = useCallback(async () => {
    if (isProcessingRef.current) return;
    isProcessingRef.current = true;

    console.log('🎉 Completing interview...');
    setStatus('completed');

    const totalScore = answersRef.current.reduce((sum, ans) => sum + ans.score, 0);
    const maxScore = answersRef.current.reduce((sum, ans) => {
      const max = ans.difficulty === 'Easy' ? 10 : ans.difficulty === 'Medium' ? 20 : 30;
      return sum + max;
    }, 0);

    await speakText(`Interview complete! Your total score is ${totalScore} out of ${maxScore} points. Thank you for your time.`);

    setTimeout(() => {
      cleanup();
      onComplete({
        ...candidate,
        answers: answersRef.current,
        completed: true,
        completedAt: Date.now(),
        totalScore,
        maxScore,
        summary: `Total Score: ${totalScore}/${maxScore} points`,
      });
    }, 3000);
  }, [candidate, onComplete, speakText, cleanup]);

  // ⭐ CRITICAL FIX: Use ref instead of callback dependency
  const startQuestionRef = useRef();

  // ⭐ FIXED: Submit answer helper - NO startQuestion dependency
  const submitAnswerHelper = useCallback(async (questionIndex, finalTranscript, currentTimeRemaining) => {
    if (isProcessingRef.current) return;

    isProcessingRef.current = true;
    setStatus('evaluating');

    const question = questions[questionIndex];
    if (!question) {
      console.error('No question found for index:', questionIndex);
      isProcessingRef.current = false;
      return;
    }

    try {
      // Score the answer
      const result = await scoreAnswerWithAI(
        question.question,
        finalTranscript || '(No answer provided)',
        question.difficulty
      );

      const newAnswer = {
        questionId: question.id,
        question: question.question,
        answer: finalTranscript,
        score: result.score,
        feedback: result.feedback,
        difficulty: question.difficulty,
        timeUsed: question.time - (currentTimeRemaining || 0),
      };

      answersRef.current = [...answersRef.current, newAnswer];
      console.log('✅ Answer saved:', newAnswer);

      // Provide feedback
      const maxScore = question.difficulty === 'Easy' ? 10 : question.difficulty === 'Medium' ? 20 : 30;
      await speakText(`You scored ${result.score} out of ${maxScore} points. ${result.feedback}`);

      // Move to next question or complete
      if (questionIndex < questions.length - 1) {
        await speakText('Moving to the next question.');

        setTimeout(() => {
          isProcessingRef.current = false;
          // ⭐ FIX: Use ref instead of direct call
          if (startQuestionRef.current) {
            startQuestionRef.current(questionIndex + 1);
          }
        }, 2000);
      } else {
        isProcessingRef.current = false;
        completeInterview();
      }
    } catch (err) {
      console.error('Error submitting answer:', err);
      setError('Failed to evaluate answer. Please try again.');
      isProcessingRef.current = false;
    }
  }, [questions, speakText, completeInterview]);

  // ⭐ FIXED: Main submit answer function
  const handleSubmitAnswer = useCallback(() => {
    if (isProcessingRef.current) {
      console.warn('⚠️ Already processing, skipping submit');
      return;
    }

    if (status !== 'answering' && status !== 'asking') {
      console.warn('⚠️ Invalid status for submit:', status);
      return;
    }

    console.log('📝 Submitting answer...');

    // Stop recording and get transcript
    const finalTranscript = stopRecording();

    // Clear timer
    if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }

    submitAnswerHelper(currentQuestionIndex, finalTranscript, timeRemaining);
  }, [status, stopRecording, currentQuestionIndex, timeRemaining, submitAnswerHelper]);

  // ⭐ FIXED: Start a question with proper state management
  const startQuestion = useCallback((index) => {
    if (isProcessingRef.current && status === 'answering') {
      console.warn('⚠️ Still processing previous question');
      return;
    }

    const question = questions[index];
    if (!question) {
      console.error('No question found for index:', index);
      return;
    }

    console.log(`📋 Starting question ${index + 1}:`, question.question);

    setCurrentQuestionIndex(index);
    setTimeRemaining(question.time);
    setTranscript('');
    setStatus('asking');

    // Initialize voice engine if needed
    if (!voiceEngine.current) {
      voiceEngine.current = new VoiceEngine();
      voiceEngine.current.setCallbacks({
        onResult: (result) => {
          setTranscript(result.full);
        },
        onSilence: () => {
          console.log('🤫 Silence detected, auto-submitting...');
          handleSubmitAnswer();
        },
        onError: (err) => {
          console.error('Voice recognition error:', err);
          setError(`Microphone error: ${err}`);
        },
      });
    }

    // ⭐ Enhanced question delivery
    let questionText = `Question ${index + 1}.`;

    if (question.type === 'introduction') {
      questionText += ' Let\'s start with an introduction.';
    } else if (question.type === 'closing') {
      questionText += ' This is our final question.';
    }

    questionText += ` ${question.question}. You have ${question.time} seconds to answer.`;

    // Speak the question
    speakText(questionText).then(() => {
      // Wait a moment after speaking, then start recording
      setTimeout(() => {
        setStatus('answering');

        const started = startRecording();

        if (started) {
          // Start timer
          if (timerRef.current) clearInterval(timerRef.current);

          timerRef.current = setInterval(() => {
            setTimeRemaining(prev => {
              if (prev <= 1) {
                console.log('⏰ Time expired, auto-submitting...');
                handleSubmitAnswer();
                return 0;
              }
              return prev - 1;
            });
          }, 1000);
        } else {
          console.error('Failed to start recording');
          setError('Failed to start voice recognition. Please check microphone permissions.');
        }
      }, 1500);
    });
  }, [questions, status, speakText, startRecording, handleSubmitAnswer]);

  // ⭐ CRITICAL: Store startQuestion in ref to avoid circular dependency
  useEffect(() => {
    startQuestionRef.current = startQuestion;
  }, [startQuestion]);

  // ⭐ FIXED: Initialize interview with proper error handling and prevent triple message
  const initializeInterview = useCallback(async () => {
    // ⭐ CRITICAL FIX: Prevent multiple initializations
    if (hasInitialized.current) {
      console.warn('⚠️ Already initialized, skipping...');
      return;
    }
    hasInitialized.current = true;

    try {
      console.log('🚀 Initializing video interview...');

      // Request camera and microphone
      const mediaStream = await navigator.mediaDevices.getUserMedia({
        video: {
          width: { ideal: 1920, min: 1280 },
          height: { ideal: 1080, min: 720 },
          facingMode: 'user',
          frameRate: { ideal: 30, min: 24 },
          aspectRatio: 16/9,
          resizeMode: 'crop-and-scale'
        },
        audio: {
          echoCancellation: true,
          noiseSuppression: true,
          autoGainControl: true,
          sampleRate: 48000,
          channelCount: 1
        }
      });

      setStream(mediaStream);
      if (videoRef.current) {
        videoRef.current.srcObject = mediaStream;
      }

      // Initialize engines
      voiceEngine.current = new VoiceEngine();
      speechEngine.current = new SpeechSynthesisEngine();
      await speechEngine.current.initialize();

      console.log('✅ Media and engines initialized');

      // Generate questions
      setStatus('generating_questions');
      const qs = await generateInterviewQuestions(
        `Name: ${candidate?.name || 'Candidate'}\nEmail: ${candidate?.email || 'email@example.com'}\n${candidate?.resumeText || ''}`,
        'Full Stack Developer'
      );

      setQuestions(qs);
      setStatus('ready');
      console.log('✅ Generated', qs.length, 'questions');

      // Welcome message - THIS WILL NOW ONLY PLAY ONCE
      await speakText(
        'Hello! Welcome to your video interview. I\'m your AI interviewer today. We\'ll have a professional conversation about your experience and skills. Let\'s begin with an introduction.'
      );

      // Start first question
      setTimeout(() => {
        if (startQuestionRef.current) {
          startQuestionRef.current(0);
        }
      }, 2000);

    } catch (err) {
      console.error('Initialization error:', err);
      setError('Failed to access camera/microphone. Please grant permissions and refresh the page.');
      setStatus('error');
      // ⭐ Reset flag on error so user can retry
      hasInitialized.current = false;
    }
  }, [candidate?.name, candidate?.email, candidate?.resumeText, speakText]);

  // Initialize on mount
  useEffect(() => {
    initializeInterview();
    return () => {
      console.log('🔄 Component unmounting, cleaning up...');
      cleanup();
    };
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  // Format time display
  const formatTime = (seconds) => {
    if (!seconds && seconds !== 0) return '0:00';
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  // Error state
  if (status === 'error') {
    return (
      <div className="min-h-screen bg-gray-900 flex items-center justify-center p-6">
        <div className="bg-white rounded-xl p-8 max-w-md text-center">
          <VideoOff className="w-16 h-16 text-red-500 mx-auto mb-4" />
          <h2 className="text-2xl font-bold text-gray-800 mb-2">Camera Access Required</h2>
          <p className="text-gray-600 mb-6">{error}</p>
          <button
            onClick={onBack}
            className="bg-indigo-600 text-white px-6 py-3 rounded-lg hover:bg-indigo-700 transition"
          >
            Go Back
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-900 p-6">
      <div className="max-w-6xl mx-auto">
        {/* Header */}
        <div className="mb-6 flex items-center justify-between">
          <button
            onClick={() => {
              if (window.confirm('Are you sure you want to exit? Your progress will be lost.')) {
                cleanup();
                onBack();
              }
            }}
            className="text-white hover:text-gray-300 transition px-4 py-2 bg-gray-800 rounded-lg"
          >
            ← Exit Interview
          </button>
          <h1 className="text-3xl font-bold text-white">Professional Video Interview</h1>
          <div className="w-32"></div>
        </div>

        {/* Video Section */}
        <div className="bg-black rounded-xl overflow-hidden mb-6 relative shadow-2xl">
          <video 
            ref={videoRef} 
            autoPlay 
            playsInline 
            muted 
            className="w-full h-[500px] object-cover" 
          />

          {/* Status Overlay */}
          <div className="absolute top-4 left-4 right-4 flex justify-between items-start">
            <div className="bg-black/80 px-4 py-3 rounded-xl backdrop-blur-md border border-white/20">
              <div className="flex items-center gap-3">
                <div className={`w-3 h-3 rounded-full ${isRecording ? 'bg-red-500 animate-pulse' : 'bg-gray-400'}`} />
                <span className="text-white text-sm font-medium">
                  {status === 'initializing' && '⏳ Setting up...'}
                  {status === 'generating_questions' && '🤖 Preparing interview...'}
                  {status === 'ready' && '✅ Ready'}
                  {status === 'asking' && '🗣️ AI Speaking'}
                  {status === 'answering' && '🎤 Your Turn to Speak'}
                  {status === 'evaluating' && '📊 Evaluating...'}
                  {status === 'completed' && '🎉 Complete!'}
                </span>
              </div>
            </div>

            {timeRemaining !== null && status !== 'completed' && (
              <div className={`px-5 py-3 rounded-xl font-bold text-xl backdrop-blur-md border-2 ${
                timeRemaining <= 10 ? 'bg-red-500/90 border-red-300 animate-pulse' : 
                timeRemaining <= 30 ? 'bg-orange-500/90 border-orange-300' : 
                'bg-blue-500/90 border-blue-300'
              } text-white shadow-lg`}>
                <Clock className="w-6 h-6 inline mr-2" />
                {formatTime(timeRemaining)}
              </div>
            )}
          </div>

          {/* AI Speaking Indicator */}
          {isAISpeaking && (
            <div className="absolute bottom-6 left-6">
              <div className="bg-purple-500/95 px-5 py-3 rounded-xl flex items-center gap-3 text-white backdrop-blur-md border-2 border-purple-300 shadow-lg">
                <Volume2 className="w-6 h-6 animate-pulse" />
                <div className="flex flex-col">
                  <span className="font-bold">AI is speaking...</span>
                  <span className="text-xs text-purple-100">Please wait for your turn</span>
                </div>
                <div className="flex gap-1 ml-2">
                  <div className="w-1 h-4 bg-white rounded-full animate-pulse"></div>
                  <div className="w-1 h-6 bg-white rounded-full animate-pulse" style={{animationDelay: '75ms'}}></div>
                  <div className="w-1 h-5 bg-white rounded-full animate-pulse" style={{animationDelay: '150ms'}}></div>
                </div>
              </div>
            </div>
          )}

          {/* Recording Indicator */}
          {isRecording && (
            <div className="absolute bottom-6 right-6">
              <div className="bg-red-500/95 px-5 py-3 rounded-xl backdrop-blur-md border-2 border-red-300 shadow-lg">
                <div className="flex items-center gap-3 text-white">
                  <Mic className="w-6 h-6 animate-pulse" />
                  <div className="flex flex-col">
                    <span className="font-bold">Recording...</span>
                    <span className="text-xs">I'm listening</span>
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* Listening Confirmation */}
          {isRecording && transcript && (
            <div className="absolute top-20 left-4">
              <div className="bg-green-500/95 px-4 py-2 rounded-lg flex items-center gap-2 text-white backdrop-blur-md border border-green-300">
                <CheckCircle className="w-5 h-5" />
                <span className="text-sm font-medium">I can hear you clearly!</span>
              </div>
            </div>
          )}

          {/* Time Warning */}
          {timeRemaining !== null && timeRemaining <= 30 && timeRemaining > 0 && status === 'answering' && (
            <div className="absolute top-20 right-4">
              <div className={`px-4 py-2 rounded-lg flex items-center gap-2 text-white backdrop-blur-md border ${
                timeRemaining <= 10 ? 'bg-red-500/95 border-red-300 animate-pulse' : 'bg-orange-500/95 border-orange-300'
              }`}>
                <AlertCircle className="w-5 h-5" />
                <span className="text-sm font-medium">
                  {timeRemaining <= 10 ? 'HURRY UP!' : 'Time running low!'}
                </span>
              </div>
            </div>
          )}
        </div>

        {/* Question Card */}
        <div className="bg-white rounded-xl p-6 mb-6 shadow-lg">
          <div className="flex items-center justify-between mb-4">
            <div>
              <h2 className="text-2xl font-bold text-gray-800">
                Question {currentQuestionIndex + 1} of {questions.length}
              </h2>
              <p className="text-sm text-gray-500 mt-1">
                {questions[currentQuestionIndex]?.type === 'introduction' && '👋 Introduction'}
                {questions[currentQuestionIndex]?.type === 'warmup' && '🔥 Warm-up'}
                {questions[currentQuestionIndex]?.type === 'technical' && '💻 Technical'}
                {questions[currentQuestionIndex]?.type === 'coding' && '⌨️ Coding'}
                {questions[currentQuestionIndex]?.type === 'scenario' && '🎯 Scenario'}
                {questions[currentQuestionIndex]?.type === 'closing' && '👋 Closing'}
              </p>
            </div>
            <span className={`px-4 py-2 rounded-full text-sm font-bold ${
              questions[currentQuestionIndex]?.difficulty === 'Easy' ? 'bg-green-100 text-green-700 border-2 border-green-300'
              : questions[currentQuestionIndex]?.difficulty === 'Medium' ? 'bg-yellow-100 text-yellow-700 border-2 border-yellow-300'
              : 'bg-red-100 text-red-700 border-2 border-red-300'
            }`}>
              {questions[currentQuestionIndex]?.difficulty || 'Loading'}
            </span>
          </div>

          <p className="text-xl text-gray-700 mb-4 leading-relaxed">
            {questions[currentQuestionIndex]?.question || 'Loading question...'}
          </p>

          <div className="w-full bg-gray-200 rounded-full h-3 overflow-hidden">
            <div 
              className="bg-gradient-to-r from-indigo-500 to-purple-600 h-3 rounded-full transition-all duration-500 shadow-inner" 
              style={{ 
                width: `${questions.length > 0 ? ((currentQuestionIndex + 1) / questions.length) * 100 : 0}%` 
              }} 
            />
          </div>
        </div>

        {/* Live Transcript */}
        {transcript && status === 'answering' && (
          <div className="bg-white rounded-xl p-6 mb-6 shadow-lg border-2 border-indigo-200">
            <div className="flex items-center justify-between mb-3">
              <div className="flex items-center gap-2">
                <Mic className="w-5 h-5 text-indigo-600 animate-pulse" />
                <h3 className="text-lg font-bold text-gray-800">Your Answer (Live)</h3>
              </div>
              <button
                onClick={handleSubmitAnswer}
                disabled={isProcessingRef.current || transcript.length < 10}
                className="bg-gradient-to-r from-green-500 to-green-600 hover:from-green-600 hover:to-green-700 text-white px-6 py-3 rounded-lg font-bold transition shadow-lg disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
              >
                <CheckCircle className="w-5 h-5" />
                Submit Answer
              </button>
            </div>
            <div className="bg-gray-50 rounded-lg p-4 border border-gray-200">
              <p className="text-gray-700 whitespace-pre-wrap leading-relaxed">
                {transcript || 'Start speaking...'}
              </p>
              <div className="mt-3 flex items-center gap-2 text-sm text-gray-500">
                <span>Words: {transcript.split(/\s+/).filter(w => w.length > 0).length}</span>
                <span>•</span>
                <span>Characters: {transcript.length}</span>
              </div>
            </div>
          </div>
        )}

        {/* Error Display */}
        {error && status !== 'error' && (
          <div className="bg-red-50 border-2 border-red-300 rounded-xl p-4 mb-6">
            <div className="flex items-center gap-3">
              <AlertCircle className="w-6 h-6 text-red-600" />
              <p className="text-red-700 font-medium">{error}</p>
            </div>
          </div>
        )}

        {/* Instructions Panel */}
        <div className="bg-gradient-to-r from-indigo-50 to-purple-50 rounded-xl p-6 border-2 border-indigo-200">
          <h3 className="text-lg font-bold text-gray-800 mb-3">💡 Interview Tips</h3>
          <ul className="space-y-2 text-sm text-gray-700">
            <li className="flex items-start gap-2">
              <span className="text-green-600 font-bold">✓</span>
              <span>Speak clearly and naturally - the AI is listening to you</span>
            </li>
            <li className="flex items-start gap-2">
              <span className="text-green-600 font-bold">✓</span>
              <span>Watch for the "I can hear you!" indicator to confirm you're being heard</span>
            </li>
            <li className="flex items-start gap-2">
              <span className="text-green-600 font-bold">✓</span>
              <span>Submit your answer manually or wait for time to expire</span>
            </li>
            <li className="flex items-start gap-2">
              <span className="text-green-600 font-bold">✓</span>
              <span>Take your time - quality matters more than speed</span>
            </li>
          </ul>
        </div>
      </div>
    </div>
  );
};

export default VideoInterviewPage;
